/**
 * Tests for briefing/agent-context.ts — generateBriefing.
 *
 * Test plan:
 *   1. All opts fields appear in the returned string in the appropriate sections.
 *   2. The string never contains the literal text "undefined" or "null".
 *   3. Required section headers are present.
 *   4. Execution sequence instructs executor to invoke /start-implementation (T7
 *      reconciliation); the skill handles impl PR creation (/pr-create) and
 *      result.json writing internally.
 *   5. Layer 2: checkpoint discipline section is always present.
 *   6. Layer 3: handover.md content is prepended when present at taskRepoRoot.
 */

import { describe, it, expect } from "vitest";
import {
  mkdtempSync,
  writeFileSync,
  mkdirSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  generateBriefing,
  type BriefingOpts,
} from "../src/briefing/agent-context.js";

const BASE_OPTS: BriefingOpts = {
  taskId: "T4",
  featureId: "agent-runtime-hardening",
  taskTitle: "Agent context generator — src/briefing/agent-context.ts",
  taskBranch: "feature/agent-runtime-hardening-T4",
  taskRepo: "workflow",
  taskRepoRoot: "/home/agent/data/workflow",
  workspaceRoot: "/home/agent/data/workspace",
  gitAuthorEmail: "agent@example.com",
  gitAuthorName: "Agent Bot",
  implementationModel: "claude-opus-4-6",
  resultPath: "/tmp/result-T4.json",
};

describe("generateBriefing", () => {
  it("returns a string", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(typeof result).toBe("string");
    expect(result.length).toBeGreaterThan(0);
  });

  it("contains taskId in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.taskId);
  });

  it("contains featureId in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.featureId);
  });

  it("contains taskBranch in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.taskBranch);
  });

  it("contains workspaceRoot in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.workspaceRoot);
  });

  it("contains gitAuthorEmail in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.gitAuthorEmail);
  });

  it("contains gitAuthorName in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.gitAuthorName);
  });

  it("contains implementationModel in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.implementationModel);
  });

  it("contains resultPath in the output", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(BASE_OPTS.resultPath);
  });

  it("does not contain the literal text 'undefined'", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).not.toContain("undefined");
  });

  it("does not contain the literal text 'null'", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).not.toContain("null");
  });

  it("includes the ## Identity section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("## Identity");
  });

  it("includes the ## Your assigned task section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("## Your assigned task");
  });

  it("includes the ## What you must do section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("## What you must do");
  });

  it("includes the ## Model section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("## Model");
  });

  it("includes the ## Rules section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("## Rules");
  });

  it("instructs writing a result file with pr_url field", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("result file");
    expect(result).toContain("terminal_status");
    expect(result).toContain("pr_url");
  });

  it("instructs executor to invoke /start-implementation (T7 reconciliation)", () => {
    const result = generateBriefing(BASE_OPTS);
    // T7 restores /start-implementation so the skill handles all execution steps
    expect(result).toContain("/start-implementation");
  });

  it("includes taskId in the /start-implementation invocation", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain(`/start-implementation ${BASE_OPTS.taskId}`);
  });

  it("still mentions /pr-create in the Rules section (executor owns impl PR)", () => {
    const result = generateBriefing(BASE_OPTS);
    // /pr-create is referenced in the Rules section (orchestrator does NOT open impl PRs)
    expect(result).toContain("/pr-create");
  });

  it("places implementationModel under the ## Model section", () => {
    const result = generateBriefing(BASE_OPTS);
    const modelIdx = result.indexOf("## Model");
    const modelValueIdx = result.indexOf(BASE_OPTS.implementationModel);
    expect(modelIdx).toBeGreaterThanOrEqual(0);
    expect(modelValueIdx).toBeGreaterThan(modelIdx);
  });

  it("places gitAuthorEmail under the ## Identity section", () => {
    const result = generateBriefing(BASE_OPTS);
    const identityIdx = result.indexOf("## Identity");
    const emailIdx = result.indexOf(BASE_OPTS.gitAuthorEmail);
    const nextSectionIdx = result.indexOf("##", identityIdx + 1);
    expect(identityIdx).toBeGreaterThanOrEqual(0);
    expect(emailIdx).toBeGreaterThan(identityIdx);
    expect(emailIdx).toBeLessThan(nextSectionIdx);
  });

  it("produces different outputs for different taskIds", () => {
    const result1 = generateBriefing(BASE_OPTS);
    const result2 = generateBriefing({ ...BASE_OPTS, taskId: "T99" });
    expect(result1).not.toBe(result2);
    expect(result2).toContain("T99");
  });

  // ── Layer 2: checkpoint discipline ───────────────────────────────────────────

  it("includes the ## Checkpoint discipline section (Layer 2)", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("## Checkpoint discipline");
  });

  it("mentions wip commit pattern in checkpoint discipline section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("wip(");
  });

  it("mentions handover.md in checkpoint discipline section", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("handover.md");
  });

  it("mentions handover_for_continuation blocked_reason in checkpoint discipline", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("handover_for_continuation");
  });

  it("includes handover_path field reference in checkpoint discipline", () => {
    const result = generateBriefing(BASE_OPTS);
    expect(result).toContain("handover_path");
  });

  // ── Layer 3: handover.md prepending ──────────────────────────────────────────

  it("does NOT prepend '## Continuing previous run' when no handover.md exists at taskRepoRoot", () => {
    // BASE_OPTS.taskRepoRoot is /home/agent/data/workflow, handover.md won't exist there
    const tmpDir = mkdtempSync(join(tmpdir(), "briefing-test-"));
    try {
      const result = generateBriefing({ ...BASE_OPTS, taskRepoRoot: tmpDir });
      expect(result).not.toContain("## Continuing previous run");
    } finally {
      rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it("prepends handover.md content when present at taskRepoRoot/handover.md (Layer 3)", () => {
    const tmpDir = mkdtempSync(join(tmpdir(), "briefing-test-"));
    const handoverContent = [
      "# Handover — T4",
      "",
      "**Terminal reason:** max_turns_exceeded",
      "**Branch:** feature/agent-runtime-hardening-T4",
      "**Last commit:** abc1234 wip: partial work",
      "",
      "## Next agent — read this first",
      "Continue from where I left off.",
    ].join("\n");

    writeFileSync(join(tmpDir, "handover.md"), handoverContent, "utf-8");

    try {
      const result = generateBriefing({ ...BASE_OPTS, taskRepoRoot: tmpDir });

      // Handover section must be present at the TOP
      expect(result).toContain("## Continuing previous run");
      expect(result).toContain("max_turns_exceeded");
      expect(result).toContain("Continue from where I left off.");

      // Handover must appear BEFORE the identity section
      const handoverIdx = result.indexOf("## Continuing previous run");
      const identityIdx = result.indexOf("## Identity");
      expect(handoverIdx).toBeLessThan(identityIdx);

      // Separator must be between handover and core briefing
      const separatorIdx = result.indexOf("---");
      expect(separatorIdx).toBeGreaterThan(handoverIdx);
      expect(separatorIdx).toBeLessThan(identityIdx);
    } finally {
      rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it("still produces a valid briefing when handover.md exists but is empty", () => {
    const tmpDir = mkdtempSync(join(tmpdir(), "briefing-test-"));
    // Write whitespace-only content — should be treated as absent
    writeFileSync(join(tmpDir, "handover.md"), "   \n  \n", "utf-8");

    try {
      const result = generateBriefing({ ...BASE_OPTS, taskRepoRoot: tmpDir });
      expect(result).not.toContain("## Continuing previous run");
      expect(result).toContain("## Identity");
    } finally {
      rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it("handles readFileSync error on handover.md gracefully — directory where file expected", () => {
    const tmpDir = mkdtempSync(join(tmpdir(), "briefing-test-"));
    // Create a directory named handover.md — readFileSync on it will throw
    mkdirSync(join(tmpDir, "handover.md"));

    try {
      // Must not throw
      expect(() => generateBriefing({ ...BASE_OPTS, taskRepoRoot: tmpDir })).not.toThrow();
      const result = generateBriefing({ ...BASE_OPTS, taskRepoRoot: tmpDir });
      // Error in reading handover → no prepend
      expect(result).not.toContain("## Continuing previous run");
    } finally {
      rmSync(tmpDir, { recursive: true, force: true });
    }
  });
});

