/**
 * Autonomous reviewer dispatch.
 *
 * Triggered when a task's status is `in_review`. The orchestrator calls
 * `dispatchReviewer` to:
 *
 *   1. Claim the review cycle by appending a `reviewer_started` log entry to
 *      the task YAML on the management-repo feature branch and pushing.
 *      First-push-wins: if the push is rejected, another agent claimed first.
 *
 *   2. Build a reviewer briefing that instructs Claude to execute /review-pr.
 *
 *   3. Submit the reviewer executor with kind="review" so the reap loop routes
 *      its completion to dispatchReviewResult (T5/T6) rather than
 *      dispatchExecutorResult.
 *
 * The reviewer writes result.json with:
 *   { terminal_status: "passed" | "change_requested" | "escalate", ... }
 */

import { execSync, spawnSync } from "node:child_process";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";
import type { Task } from "../types/task.js";
import { buildGitEnv } from "../git-env.js";
import { SubProcessAdapter } from "../adapters/executor/subprocess.js";
import type { ExecutorPortInput, CompletionBrokerPort } from "@workflow/runtime-abi";
import { taskYamlRelPath } from "../paths.js";
import { readTask, writeTask } from "../utils/task-yaml-io.js";
import { writeBriefing } from "../briefing/write-briefing.js";
import { generateReviewerBriefing } from "../briefing/reviewer-briefing.js";

// ── Public types ──────────────────────────────────────────────────────────────

export type ReviewerDispatchOutcome =
  | "claim_lost"
  | "dispatched";

export interface DispatchReviewerOptions {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  implRepoRoot: string;
  /** SSH or HTTPS URL of the implementation repo. */
  implRepoUrl: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  workflowLocalPath: string;
  maxTurns: number;
  maxTokens: number;
  logSinkEnabled: boolean;
  reviewerModel: string;
  workspaceId: string;
  githubToken: string;
  /** Max review cycles before escalating. Default: 3. */
  maxReviewCycles?: number;
  /** Completion broker for async submit. */
  broker: CompletionBrokerPort;
  /** Callback URL the runner wrapper will POST to. Pre-computed by caller. */
  callbackUrl: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/** Count in_review log entries — used to enforce the cycle limit. */
function countReviewCycles(task: Task): number {
  return task.log.filter((e) => e.action === "reviewer_started").length;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Claim and dispatch a reviewer executor for a task in `in_review` status.
 *
 * Returns "claim_lost" when another agent already claimed this review cycle,
 * or "dispatched" when the reviewer was successfully submitted.
 */
export async function dispatchReviewer(
  opts: DispatchReviewerOptions,
): Promise<ReviewerDispatchOutcome> {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    implRepoRoot,
    implRepoUrl,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    workflowLocalPath,
    maxTurns,
    maxTokens,
    logSinkEnabled,
    reviewerModel,
    workspaceId,
    githubToken,
    maxReviewCycles = 3,
    broker,
    callbackUrl,
    emit,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  // ── 1. Checkout and reset task branch in management repo ──────────────────────
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  // ── 2. Read task and guard against duplicate claims ───────────────────────────
  let task: Task;
  try {
    task = readTask(workspaceRoot, featureId, taskId);
  } catch (e) {
    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  if (task.status !== "in_review") {
    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: `task status is ${task.status}, expected in_review` });
    return "claim_lost";
  }

  // Duplicate-claim guard: if the last log action is already `reviewer_started`,
  // another orchestrator instance claimed this cycle first.
  const lastEntry = task.log[task.log.length - 1];
  if (lastEntry?.action === "reviewer_started") {
    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is reviewer_started — already claimed" });
    return "claim_lost";
  }

  const reviewCycleCount = countReviewCycles(task);

  // ── 3. Write reviewer_started log entry and push (first-push-wins) ───────────
  const now = new Date().toISOString();
  task.log.push({
    action: "reviewer_started",
    by: gitAuthorEmail,
    at: now,
    note: `Reviewer dispatch claimed (cycle ${reviewCycleCount + 1} of ${maxReviewCycles}).`,
  });
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  writeTask(workspaceRoot, featureId, task);

  const relPath = taskYamlRelPath(featureId, taskId);
  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): reviewer_started — claim cycle ${reviewCycleCount + 1}"`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
    return "claim_lost";
  }

  let claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env, encoding: "utf-8",
  });

  if (claimPush.status !== 0) {
    // Push rejected — rebase onto origin and re-check duplicate-claim guard.
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
      execSync(`git -C "${workspaceRoot}" rebase origin/${taskBranch}`, { env, stdio: "pipe" });
    } catch (e) {
      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: `rebase failed after push rejection: ${String(e)}` });
      return "claim_lost";
    }

    const rebasedTask = readTask(workspaceRoot, featureId, taskId);
    if (rebasedTask.status !== "in_review") {
      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: `task status changed to ${rebasedTask.status} during rebase` });
      return "claim_lost";
    }
    const rebasedLast = rebasedTask.log[rebasedTask.log.length - 1];
    if (rebasedLast?.action === "reviewer_started") {
      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: "another agent claimed during rebase" });
      return "claim_lost";
    }

    claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
      env, encoding: "utf-8",
    });
    if (claimPush.status !== 0) {
      emit({ type: "reviewer_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
      return "claim_lost";
    }
  }

  emit({ type: "reviewer_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr?.url, cycle: reviewCycleCount + 1 });

  // ── 4. Build reviewer briefing and submit executor (kind=review) ──────────────
  const resultPath = join(tmpdir(), `reviewer-result-${taskId}.json`);

  const reviewerBriefing = generateReviewerBriefing({
    taskId,
    featureId,
    taskTitle: task.title,
    taskBranch,
    taskRepo: task.repo,
    taskRepoRoot: implRepoRoot,
    workspaceRoot,
    prUrl: task.pr?.url ?? "",
    gitAuthorEmail,
    gitAuthorName,
    reviewerModel,
    resultPath,
    reviewCycleCount,
    maxReviewCycles,
  });

  const { briefingPath } = writeBriefing({ taskId: `reviewer-${taskId}`, briefingContent: reviewerBriefing });
  const nonce = randomUUID();

  const input: ExecutorPortInput = {
    taskId,
    featureId,
    workspaceId,
    taskRepoUrl: implRepoUrl,
    taskRepoBranch: taskBranch,
    taskRepoPath: implRepoRoot,
    briefingPath,
    resultPath,
    budgetTokens: maxTokens,
    implementationModel: reviewerModel,
    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
    githubToken,
    callbackUrl,
    nonce,
  };

  const reviewerAdapter = new SubProcessAdapter({
    broker,
    handleKind: "review",
    extraEnv: {
      WORKSPACE_ROOT: workspaceRoot,
      TASK_BRANCH: taskBranch,
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_AUTHOR_NAME: gitAuthorName,
      WORKFLOW_LOCAL_PATH: workflowLocalPath,
      MAX_TURNS: String(maxTurns),
      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
      MAX_REVIEW_CYCLES: String(maxReviewCycles),
      GITHUB_TOKEN: githubToken,
    },
  });

  const handle = await reviewerAdapter.submit(input);

  emit({
    type: "reviewer_submitted",
    task_id: taskId,
    feature_id: featureId,
    handle,
    cycle: reviewCycleCount + 1,
  });

  return "dispatched";
}

